// DeclaredExceptions returns the declared exceptions.
func DeclaredExceptions() []Exception {
package netdiag

import (
	"context"
	"net/netip"
	"slices"
	"strings"
	"testing"

	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/command"
