	}
	if len(pmHopTTLs(m.pathModel)) != 0 {
		t.Errorf("hops = %v, want the previous rows cleared", pmHopTTLs(m.pathModel))
	}
	if cmd == nil {
		t.Error("no Cmd: the second trace would never start")
	}
}

