17	// GetTitle implements HeaderView
18	func (m *Model) GetTitle() string {
19		base := theme.IconNetwork + " Network"
20		if m.activeTab == tabDiagnostics && m.state == StateTrace {
21			return m.traceTitle(base)
22		}
23		if m.state == StateDetails {
24			if label := m.selected.Title; label != "" {
