255	// RenderFooter implements FooterView
256	func (m *Model) RenderFooter(width int) string {
257		var parts []string
258	
259		// The active tab's filter bar renders above the tab bar when visible; on
260		// Path the target field takes that slot in every state.
261		switch {
262		case m.activeTab == tabPath:
263			parts = append(parts, m.pathModel.barView(width))
264		case m.activeTab == tabPorts && m.portsModel.table.FilterBar().IsVisible():
265			parts = append(parts, m.portsModel.table.FilterBar().View())
266		case m.activeTab == tabDiagnostics && m.filterBar.IsVisible():
267			parts = append(parts, m.filterBar.View())
268		case m.activeTab == tabInterfaces && m.interfacesModel.table.FilterBar().IsVisible():
269			parts = append(parts, m.interfacesModel.table.FilterBar().View())
270		case m.activeTab == tabForward && m.forwardModel.table.FilterBar().IsVisible():
271			parts = append(parts, m.forwardModel.table.FilterBar().View())
272		}
273	
274		tabs := theme.RenderTabs([]theme.TabItem{
275			{Label: "Diagnostics"},
276			{Label: "Ports"},
277			{Label: "Interfaces"},
278			{Label: "Forward"},
279			{Label: "Path"},
280		}, m.activeTab)
281		tabBar := theme.PadWithBg(theme.Bg(" ")+tabs, width)
282	
283		// The message belongs to the tab that raised it: each sub-model keeps its
284		// own, so switching away does not carry one tab's notice onto another.
285		footer, status := m.activeFooter()
286		parts = append(parts, tabBar, theme.EmptyLineBg(width), footer.View(width, status))
287		return strings.Join(parts, "\n")
288	}
