379			t.Error("InEditMode() = true in the ready sub-level")
380		}
381		m = feed(t, m, testutil.Key("ctrl+o"))
382		if !m.InEditMode() {
383			t.Error("InEditMode() = false with the selector open")
384		}
385	}
386	
387	// A failed run stays in the sub-level with its error, and enter retries.
388	func TestTraceLevelAFailedRunStaysInTheSubLevelWithItsError(t *testing.T) {
389		m, _, _ := traceLevelModel(t, traceLevelHost)
390		m = feed(t, m, pathDoneMsg{gen: m.pathModel.gen, err: context.DeadlineExceeded})
391	
392		pm := m.pathModel
393		if m.state != StateTrace || pm.state != pathDone || pm.errText == "" {
394			t.Fatalf("state=%v pathState=%v errText=%q, want StateTrace, pathDone and the error", m.state, pm.state, pm.errText)
395		}
396		if pm.InEditMode() {
397			t.Error("the Path model's hidden field took the keyboard back")
398		}
399		gen := pm.gen
400		m = feed(t, m, testutil.Key("enter"))
401		if !m.pathModel.running() || m.pathModel.gen != gen+1 {
402			t.Errorf("running=%v gen %d->%d, want enter to try again", m.pathModel.running(), gen, m.pathModel.gen)
403		}
404		_ = nettrace.OutcomeReached
405	}
