36	// GetShortcuts implements HeaderView
37	func (m *Model) GetShortcuts() shortcut.Shortcuts {
38		tabShortcuts := shortcut.Shortcuts{
39			{Key: "tab", Description: "Switch tab"},
40		}
41	
42		if m.activeTab == tabPath {
43			return m.pathModel.shortcuts()
44		}
45	
46		if m.activeTab == tabInterfaces {
47			// A read in flight greys the table's keys rather than removing them:
48			// the tab is the same screen either side of a refresh, and a column
49			// that empties and refills on every ctrl+r is the flicker Rule 130 is
50			// about. ctrl+r stays lit — asking again is exactly what still applies.
51			loading := m.interfacesModel.loading
52			return append(tabShortcuts, shortcut.Shortcuts{
53				{Key: "ctrl+r", Description: "Refresh"},
54				{Key: "/", Description: "Filter", Disabled: loading},
55				{Key: ".", Description: "Sort", Disabled: loading},
56				{Key: "?", Description: "Help"},
57			}...)
58		}
59	
60		if m.activeTab == tabForward {
61			if m.forwardModel.form != nil {
62				// A form is a mode, so the whole list is replaced rather than
63				// greyed (Rule 130): greying N and K here would show the union of
64				// two vocabularies.
65				return shortcut.Shortcuts{
66					// ←→ only cycles the type, so it greys elsewhere (Rule 130).
67					{Key: "←→", Description: "Change type", Disabled: !m.forwardModel.form.TypeFocused()},
68					{Key: "enter", Description: "Open the forward"},
69					{Key: "esc", Description: "Cancel"},
70				}
71			}
72			if m.forwardModel.table.FilterBar().InEditMode() {
73				return shortcut.Shortcuts{
74					{Key: "enter/esc", Description: "Confirm / Cancel search"},
75				}
76			}
77			return append(tabShortcuts, shortcut.Shortcuts{
78				{Key: keymap.New, Description: "New forward"},
79				// Nothing to pause, resume or delete on an empty table (Rule 130).
80				{Key: "space", Description: m.forwardModel.toggleLabel(), Disabled: !m.forwardModel.switchable().Enabled()},
81				{Key: keymap.Kill, Description: "Delete forward", Disabled: !m.forwardModel.closable().Enabled()},
82				{Key: "/", Description: "Search"},
83				{Key: ".", Description: "Sort"},
84				{Key: "?", Description: "Help"},
85			}...)
86		}
87	
88		if m.activeTab == tabPorts {
89			if m.portsModel.table.FilterBar().InEditMode() {
90				return shortcut.Shortcuts{
91					{Key: "enter/esc", Description: "Confirm / Cancel search"},
92				}
93			}
94			sc := shortcut.Shortcuts{
95				{Key: "t", Description: "Toggle TCP"},
96				{Key: "u", Description: "Toggle UDP"},
97				{Key: "l", Description: "Toggle LISTEN"},
98				{Key: "e", Description: "Toggle ESTAB"},
99				{Key: "n", Description: "Toggle numeric"},
100				{Key: "z", Description: "Reset filters"},
101				{Key: "/", Description: "Search"},
102				{Key: "space", Description: "Pause/Resume"},
103				// A socket the system declines to attribute carries no PID, so
104				// there is nothing to signal (Rule 130).
105				{Key: keymap.Kill, Description: "Kill process", Disabled: !m.portsModel.killable().Enabled()},
106				{Key: "?", Description: "Help"},
107			}
108			return append(tabShortcuts, sc...)
109		}
110	
111		switch m.state {
112		case StateTrace:
113			return m.traceShortcuts()
114		case StateInput:
115			enter := shortcut.Shortcut{Key: "enter", Description: "Run the checks"}
116			if m.focusedField == fieldTraceButton {
117				enter = shortcut.Shortcut{Key: "enter", Description: "Trace the path", Disabled: !m.traceable().Enabled()}
118			}
119			return append(tabShortcuts, shortcut.Shortcuts{
120				enter,
121				{Key: "?", Description: "Help"},
122			}...)
123		case StateRunning:
